"use strict";
// Optional chapter: fictional records stay separate from sourced historical reading.
let nightPhotoZoom=false;
const nightKeys=['draft','chat','forum','photo','receipt','after'];
function nightState(){if(!tideDeep.night||!Array.isArray(tideDeep.night.read))tideDeep.night={read:[],checked:false,reply:'',choice:''};return tideDeep.night;}
try{const n=JSON.parse(localStorage.getItem(tideStoreKey)||'null')?.expansion?.night;if(n)tideDeep.night={read:nightKeys.filter(k=>Array.isArray(n.read)&&n.read.includes(k)),checked:n.checked===true&&['draft','chat','forum','photo','receipt'].every(k=>n.read?.includes(k)),reply:'',choice:['wait','ask'].includes(n.choice)?n.choice:''};}catch{}
function nightRead(k){const n=nightState();if(nightKeys.includes(k)&&!n.read.includes(k)){n.read.push(k);tideSave();}}
function nightCheck(time,claim){const n=nightState();if(tide.device!=='black'||!['draft','chat','forum','photo','receipt'].every(k=>n.read.includes(k)))return '这份记录还有空白。先保留草稿，不替失主补上没有留下来的事。';if(String(time).replace(/[^0-9]/g,'')!=='2240'||claim!=='unknown')return '时间和结论不能混为一件事。票上写了什么，和他实际做了什么，是两回事。';n.checked=true;tideSave();return '纸条已夹进记录袋。暂记：有出发计划，是否乘车未确认。没有改动手机里的原记录。';}
function nightReply(choice){const n=nightState();if(!n.checked||!['wait','ask'].includes(choice)||tide.device!=='black')return false;n.choice=choice;tideSave();return true;}
function nightNav(){return `<nav class="night-tabs" aria-label="许舟的本机资料">${deepLink('page:night-index','存储卡 / 末班车之后')}${deepLink('page:night-period','2008年剪报')}</nav>`;}
const nightDocuments={
 draft:['草稿箱 / 未发送',`<small>短信草稿 · 10-17 22:31 · 收件人：妈</small><p>我先去买两节电池。回去要是过了十二点，你别出来接，我带钥匙了。</p><hr><small>短信草稿 · 10-18 03:46 · 收件人：阿巡</small><p>你刚才是不是来过？我把门开了一点，楼道灯亮着，没人。我没有带录音机回来，为什么屋里也有那个转轴声。</p><hr><small>短信草稿 · 时间未保存 · 收件人空白</small><p>别回这条。回了以后，它就知道这个号码还能用。</p><p class="night-muted">最后一条仅有草稿正文，没有发送回执，不能确定写入顺序。</p>`],
 chat:['QQ / 阿巡 · 离线记录',()=>deepBubbles([['阿巡','昨晚网断了两次。我把你离线发的几句抄下来，别拿现在的聊天时间当昨晚发生的时间。','10-19 00:37'],['许舟（旧记录）','票拍糊了没有？四块钱还得留着报账。','10-17 22:36'],['阿巡（旧记录）','清楚，电池买了没？','10-17 22:37'],['许舟（旧记录）','老板关门了。公交站还亮着。','10-17 22:38'],['阿巡','后面没了。我没看见他上车，也没跟他一起去。','10-19 00:38'],['阿巡','他平常什么都拍：吃饭、作业、票根。那张早餐也留着吧，别把他的手机弄得只剩那一晚。','10-19 00:40']])],
 forum:['回声采集 / 末班车有人坐过吗',`<small>本机缓存 · 2008-10-18 · 原创虚构论坛</small><section><b>1楼 / 夜班修车 / 11:26</b><p>东站那块站牌换过一次。末班时间是计划，不是每次真按点。别凭一张票认人，我晚上只记得一个人问买电池的店关没关。</p></section><section><b>2楼 / 盐汽水 / 11:42</b><p>海边有个门一直响，是风。那天我白天去过，晚上没去，别引用成我在现场。</p></section><section><b>3楼 / 听潮的人 / 12:03</b><p>我回去以后，窗户关着。声音不是从窗户来的。</p></section><section><b>4楼 / 版主 / 12:20</b><p>第三楼是原帖的引用还是本人回复，缓存缺了标记。先别往外传。谁存了完整页，留着原文件。</p></section><section><b>5楼 / 未显示昵称 / 时间缺失</b><p>如果听见门外的人先叫出你的名字，先看一下它是从哪一年的帖子里学到的。</p></section>`],
 photo:['相册 / 留存联的局部',()=>`<button data-night-zoom>整图 / 放大局部</button><figure class="night-detail ${nightPhotoZoom?'is-zoomed':''}"><img src="images/tide/deep/ticket.svg" alt="原创故事车票图：东站至老码头，22:40，四元，座号09"></figure><p>同一张照片的放大阅读，原文件仍在相册。页面底部记录的拍照时间是22:35。</p><p>拖动图片区域可看局部；屏幕小的话也可回相册用放大查看。纸面上的字与照片的文件时间需要分开读。</p>${deepLink('deepphoto:ticket','打开原相册文件')}`],
 receipt:['浏览器 / 报账备忘',`<small>本地便笺 · 10-17 21:50 · 许舟</small><p>交通费：留票；电池：没发票就在背面写店名。录音机留在店里，老板说先测皮带。今晚只带手机和耳机。</p><p>交报告前把四块车费和班长那三块分开。不要再把旧票混进去。</p><hr><p>10-18补记：电池没买到。回来的路很长，记不清从哪一段开始没听见自己的脚步声。到家后先拍了窗户。</p><p class="night-muted">本机便笺没有修改历史，补记不能单独证明行程。</p>`]
};
function nightPage(id){const n=nightState();if(id==='index')return tideFrame('存储卡 / PRIVATE',`<div class="night-card"><small>许舟的存储卡 · 2008</small><h3>末班车之后</h3><p>几份文件夹在作业和铃声之间。谁也没有把它们整理成一个故事。</p><div class="night-filelist">${[['draft','草稿 / 三条未发短信'],['chat','QQ / 阿巡的离线抄录'],['photo','相册 / 留存联局部'],['receipt','便笺 / 报账备忘'],['forum','论坛 / 末班车有人坐过吗'],['note','随手记 / 当晚的空白']].map(([k,t])=>deepLink('page:night-'+k,t)).join('')}</div>${n.checked?deepLink('page:night-after','收件箱 / 后来的一条'):''}<small>本段剧情为原创虚构；可随时返回游戏和音乐。</small></div>${deepLink('deep:history','返回浏览器')}`);
if(id==='period')return tideFrame('2008 / 网络剪报',`<article class="night-card"><small>真实史料摘要 · 不属于案件证据</small><h3>Firefox 3 发布</h3><p>2008年6月17日，Mozilla发布Firefox 3。智能地址栏能利用历史记录、书签和标签帮助查找网站；整页缩放也是当次版本介绍的功能。发布同时启动Download Day下载活动。</p><a href="https://blog.mozilla.org/press/2008/06/mozilla-releases-firefox-3-and-redefines-the-web-experience/" target="_blank" rel="noopener">来源：Mozilla当年新闻稿</a><h3>Android 1.0 SDK</h3><p>2008年9月23日，Android开发者博客宣布Android 1.0 SDK，配合首款Android手机T-Mobile G1的公布。那时，新平台的软件开发工具刚开始走向更多开发者。</p><a href="https://android-developers.googleblog.com/2008/09/announcing-android-10-sdk-release-1.html" target="_blank" rel="noopener">来源：Android开发者博客</a><p class="night-muted">中文摘要依据官方原文整理，非原站页面复制。链接打开史料来源。</p></article>${deepLink('page:night-index','返回存储卡')}`);
if(id==='note')return tideFrame('随手记 / 留一个空白',`<div class="night-card"><p>你可以把确定的字抄下来，把没有凭据的地方空着。</p><form data-night-note><label>车票上的发车时间<input name="time" maxlength="8" inputmode="numeric" placeholder="时：分" aria-label="车票发车时间"></label><label>关于当晚乘车<select name="claim" aria-label="乘车判断"><option value="">暂未填写</option><option value="yes">确定上车了</option><option value="no">确定没有上车</option><option value="unknown">尚无记录确认</option></select></label><button>夹进记录袋</button></form>${n.reply?`<p role="status">${escapeHTML(n.reply)}</p>`:''}${n.checked?deepLink('page:night-after','看后来留下的消息'):''}</div>${deepLink('page:night-index','返回存储卡')}`);
if(id==='after'){if(!n.checked)return nightPage('index');nightRead('after');return tideFrame('短信 / 未署名',`<div class="night-card"><small>剧情消息 · 整理记录之后</small>${deepBubbles([['未知发件人','你没把空白填上。谢谢。','未显示时间'],['未知发件人','这部手机里还有白天。别只在夜里找我。','随后']])}${!n.choice?`<button data-night-reply="wait">不回复，保留原记录</button><button data-night-reply="ask">问：你是谁？</button>`:`<p>${n.choice==='ask'?'发送失败。重试按钮下面多出一行旧草稿：“问过了，别再问。”':'你没有回复。屏幕暗下去时，消息的时间一栏仍然是空的。'}</p><p>阿巡的头像亮了：周一报告还要交。照片别删，早餐那张也别删。</p><small>这段记录已保留。主线和其他手机仍可继续探索。</small>`}</div>${deepLink('page:night-index','返回存储卡')}`);}
const doc=nightDocuments[id];if(!doc)return '';nightRead(id);return tideFrame(doc[0],`<article class="night-card">${typeof doc[1]==='function'?doc[1]():doc[1]}</article>${deepLink('page:night-index','返回存储卡')}`);}
const nightBrowserBase=tideBrowser;tideBrowser=function(){if(tide.device==='black'&&tideView.startsWith('page:night-'))return nightPage(tideView.slice(11));const html=nightBrowserBase();return tide.device==='black'?html+nightNav():html;};
const nightSmsBase=tideSms;tideSms=function(){const html=nightSmsBase();return tide.device==='black'?html+`<nav class="night-tabs">${deepLink('page:night-draft','草稿箱 / 未发送')}</nav>`:html;};
const nightQQBase=tideQQ;tideQQ=function(){const html=nightQQBase();return tide.device==='black'?html+`<nav class="night-tabs">${deepLink('page:night-chat','阿巡 / 离线抄录')}</nav>`:html;};
const nightForumBase=tideForum;tideForum=function(){const html=nightForumBase();return tide.device==='black'?html+`<nav class="night-tabs">${deepLink('page:night-forum','末班车有人坐过吗 / 5楼')}</nav>`:html;};
const nightAlbumBase=tideAlbum;tideAlbum=function(){const html=nightAlbumBase();return tide.device==='black'?html+`<nav class="night-tabs">${deepLink('page:night-photo','留存联 / 查看局部')}</nav>`:html;};
document.addEventListener('submit',e=>{if(!tide.active||tide.device!=='black'||!e.target.matches('[data-night-note]'))return;e.preventDefault();const f=new FormData(e.target);nightState().reply=nightCheck(f.get('time'),f.get('claim'));tideSave();refreshPhone();});
document.addEventListener('click',e=>{const z=e.target.closest('[data-night-zoom]');if(z&&tide.active&&tide.device==='black'){e.preventDefault();nightPhotoZoom=!nightPhotoZoom;refreshPhone();return;}const b=e.target.closest('[data-night-reply]');if(!b||!tide.active)return;e.preventDefault();if(nightReply(b.dataset.nightReply))refreshPhone();});
